<?php
 namespace QQWorld\Checkout\Observer; use QQWorld\Framework\Event\ObserverInterface; class LoadCustomerQuoteObserver implements ObserverInterface { protected $checkoutSession; protected $messageManager; public function __construct( \QQWorld\Checkout\Model\Session $checkoutSession, \QQWorld\Framework\Message\ManagerInterface $messageManager ) { $this->checkoutSession = $checkoutSession; $this->messageManager = $messageManager; } public function execute(\QQWorld\Framework\Event\Observer $observer) { try { $this->checkoutSession->loadCustomerQuote(); } catch (\QQWorld\Framework\Exception\LocalizedException $e) { $this->messageManager->addError($e->getMessage()); } catch (\Exception $e) { $this->messageManager->addException($e, __('Load customer quote error')); } } } 